:root {
  /* Colors */
  --color-paper-canvas: #fcfcfc;
  --color-mist-surface: #f8f8f8;
  --color-frosted-panel: #ffffff;
  --color-smoke-wash: #0000000a;
  --color-jet-action: #000000;
  --color-ink: #191919;
  --color-graphite-chip: #363636;
  --color-ash-caption: #1919198f;
  --color-fog-hint: #19191966;
  --color-quartz-border: #00000014;
  --color-signal-blue: #317cff;
  --color-moss-pass: #00a558;
  --color-ember-diff: #f53b3a;

  /* Typography — Font Families */
  --font-nb-international-pro: "NB International Pro", Geist, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-inter: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-sf-mono: "SFMono-Regular", "Geist Mono", ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;

  /* Typography — Scale */
  --text-small: 12px;
  --leading-small: 1.333;
  --tracking-small: 0px;
  --text-caption: 13px;
  --leading-caption: 1.385;
  --tracking-caption: -0.065px;
  --text-body-sm: 14px;
  --leading-body-sm: 1.4;
  --tracking-body-sm: 0px;
  --text-body: 16px;
  --leading-body: 1.4;
  --tracking-body: 0px;
  --text-subheading: 20px;
  --leading-subheading: 1.2;
  --tracking-subheading: -0.2px;
  --text-heading-sm: 22px;
  --leading-heading-sm: 1.273;
  --tracking-heading-sm: -0.33px;
  --text-heading: 32px;
  --leading-heading: 1.2;
  --tracking-heading: -0.64px;
  --text-heading-lg: 40px;
  --leading-heading-lg: 1.04;
  --tracking-heading-lg: -1.2px;
  --text-display: 64px;
  --leading-display: 1.0;
  --tracking-display: -1.92px;

  /* Typography — Weights */
  --font-weight-regular: 400;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;

  /* Spacing */
  --spacing-1: 1px;
  --spacing-2: 2px;
  --spacing-4: 4px;
  --spacing-6: 6px;
  --spacing-7: 7px;
  --spacing-8: 8px;
  --spacing-12: 12px;
  --spacing-14: 14px;
  --spacing-16: 16px;
  --spacing-20: 20px;
  --spacing-24: 24px;
  --spacing-28: 28px;
  --spacing-32: 32px;
  --spacing-40: 40px;
  --spacing-60: 60px;
  --spacing-120: 120px;

  /* Layout */
  --page-max-width: 1400px;
  --content-width: 1280px;
  --page-gutter: 60px;
  --section-gap: 120px;
  --card-padding: 24px;
  --element-gap: 8px;
  --nav-height: 94px;

  /* Border Radius */
  --radius-sm: 3px;
  --radius-md: 4px;
  --radius-lg: 6px;
  --radius-xl: 8px;
  --radius-xl-2: 10px;
  --radius-2xl: 12px;
  --radius-2xl-2: 16px;
  --radius-3xl: 20px;
  --radius-full: 9999px;

  /* Named Radii */
  --radius-buttons: 9999px;
  --radius-pills: 200px;
  --radius-avatars: 9999px;
  --radius-small-cards: 20px;
  --radius-inputs: 16px;
  --radius-cards: 12px;
  --radius-inner-tiles: 10px;
  --radius-alert-banners: 8px;
  --radius-small-elements: 6px;
  --radius-tags: 4px;
  --radius-images: 3px;
  --radius-sections: 0px;

  /* Shadows */
  --shadow-subtle: 0px 1px 2px 0px rgba(0, 0, 0, 0.05);
  --shadow-sm: 0px 1px 3px 0px rgba(0, 0, 0, 0.06), 0px 1px 2px 0px rgba(0, 0, 0, 0.06);
  --shadow-md: 0px 10px 15px -3px rgba(0, 0, 0, 0.06);
  --shadow-md-2: 0px 13px 10px 0px rgba(0, 0, 0, 0.06);
  --shadow-xl: 0px 25px 50px -12px rgba(0, 0, 0, 0.25);

  /* Surfaces */
  --surface-paper-canvas: #fcfcfc;
  --surface-mist-surface: #f8f8f8;
  --surface-frosted-panel: #ffffff;
  --surface-smoke-wash: #0000000a;
  --surface-jet-action: #000000;
}

